registerRefData('nsw-cond-n-5351',{"id":5351,"pan":null,"ref":"DA16/0789","address":"16 Chapman Street Werrington","description":"Residential - Multi Unit","outcome":null,"outcome_raw":"","outcome_source":"planning_panels","determined":"1900-01-01","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2016SYW159!20190614T223644.322 GMT","sha256":"6dfc8b98ea46ea36d40ccaee0e2dab5b2429a44f7a2c1c3f24dec986f901d58b","pages":46,"layout":"numbered","n":89,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/5351.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/residential-multi-unit","lga":"PENRITH","conditions":[{"label":"1","code":null,"number":"1","title":"The development must be implemented substantially in accordance with the approved","text":"plans and other plans or documents approved under this Consent, except as may be\namended in red on the attached plans and by the following conditions:\nDrawing No. Drawing Title Revision Prepared by Dated\nA0000-CS Cover Sheet 8 The Bathla Group 25 October 2017\nA001-CT Compliance Tables 7 The Bathla Group 23 October 2017\nA002-SD Subdivision Plan 6 The Bathla Group October 2017\nA003-SA Concept Site Locality Plan 5 The Bathla Group 8 August 2017\nA004 - SD Subdivision of Proposed Lot 3 6 The Bathla Group October 2017\nA005 Site Plan Lot 31 and Lot 32 5 The Bathla Group 8 August 2017\nA007-SP Site Plan 8 The Bathla Group 25 October 2017\nA2000-P2 Basement 2 8 The Bathla Group 25 October 2017\nA2001-P1 Basement 1 7 The Bathla Group 23 October 2017\nA2002-0G Ground 8 The Bathla Group 25 October 2017\nA2003-01 Level 1 8 The Bathla Group 25 October 2017\nA2004-02 Level 2 8 The Bathla Group 25 October 2017\nA2005-03 Level 3 8 The Bathla Group 25 October 2017\nA2006-04 Level 4 8 The Bathla Group 25 October 2017\nA2007-05 Roof 6 The Bathla Group October 2017\nA2008 Block A 8 The Bathla Group 25 October 2017\nA2009 Block B 8 The Bathla Group 25 October 2017\nAppeal No. 63151 of 2017\nA2010 Block C-1 8 The Bathla Group 25 October 2017\nA2011 Block C-2 8 The Bathla Group 25 October 2017\nA2020-SC Site Section 8 The Bathla Group 25 October 2017\nA2021-SC Site Section 8 The Bathla Group 25 October 2017\nA2022-SC Sections 8 The Bathla Group 25 October 2017\nA2023-SC Sections 8 The Bathla Group 25 October 2017\nA2030-SE Site Elevations 8 The Bathla Group 25 October 2017\nA2031-SE Site Elevations 8 The Bathla Group 25 October 2017\nA2032-SE Internal Elevations 8 The Bathla Group 25 October 2017\nA2033-SE Internal Elevations 8 The Bathla Group 25 October 2017\n,\nA2034-EF A External Colours and Finishes8 The Bathla Group 25 October 2017 I\nA2034 EF B External Colours and Finishes\n2\n8 The Bathla Group 25 October 2017\nA2035-EM External Materials 8 The Bathla Group 25 October 2017\nA2060-AU Adaptable Units 8 The Bathla Group 25 October 2017\nA2061-LU Liveable Units 8 The Bathla Group 25 October 2017\nA2062-TU Typical Unit Dimensions 8 The Bathla Group 25 October 2017\nA2062A Typical 1 Bed Units 8 The Bathla Group 25 October 2017\nA2062B Typical 2 Bed Units 8 The Bathla Group 25 October 2017\nA2062C Typical 3 Bed Units 8 The Bathla Group 25 October 2017\nA2063-FD Fence Detail 8 The Bathla Group 25 October 2017\nA2064 FD Fence and Main Entry 8 The Bathla Group 25 October 2017\nA2090-HL 3D Height Limit 6 The Bathla Group October 2017\n- Stormwater Management\nReport\nAurecon 9 October 2017\nCC-0400 Cover Sheet 4 Aurecon\nCC-0401 General Notes Sheet 1 of 2 4 Aurecon 9 October 2017\nAppeal No. 63151 of 2017\nCC-0402 General Notes Sheet 2 of 2 4 Aurecon 9 October 2017\nCC-0403 Survey Plan 4 Aurecon 9 October 2017\nCC-0404 Site Layout Plan 4 Aurecon 9 October 2017\nCC-0405 Erosion and Sedimentation\nControl Plan","stage":"general","stage_basis":"heading","page":11},{"label":"4","code":null,"number":"4","title":"Aurecon 9 October 2017","text":"CC-0406 Erosion and Sedimentation\nControl Details\n4 Aurecon 9 October 2017\nCC-04010 General Arrangement Plan\nSheet 1 of 2\n4 Aurecon 9 October 2017\nCC-04011 General Arrangement Plan\nSheet 2 of 2\n4 Aurecon 9 October 2017\nCC-0412 Stormwater Onsite Detention\nTank Details\n4 Aurecon 9 October 2017\n- BASIX Certificate\nReference No. 726068M-03\n(Pages 1 - 35)\n- SLR Consulting 19 October 2017\n- Amended Bushfire Protection\nAssessment\n- ABPP Pty Ltd 29 August 2017\n- Access Report C Ergon Consulting 19 June 2017\n- DA Acoustic Assessment 5 Acoustic Logic 11 September\n2017\nArboricultural Impact\nAssessment\nUrban Forestry\nAustralia\nSeptember 2017\n2 The development shall not be used or occupied until an Occupation Certificate has\nbeen issued.\n3 A Construction Certificate shall be obtained prior to commencement of any building\nworks.\n4 A Copy of the Bushfire Safety Authority issued by the NSW Rural Fire Service dated\n19 September 2017 shall be submitted to the Principal Certifying Authority, before\nthe Construction Certificate can be issued for the same development and the\nrequirements of this Authority are to be complied with.\nAppeal No. 63151 of 2017\nA copy of the approval shall be submitted to Penrith City Council with the copy of the\nConstruction Certificate, if Council is not the Principal Certifying Authority.","stage":"general","stage_basis":"heading","page":13},{"label":"5","code":null,"number":"5","title":"","text":"The work must be carried out in accordance with the requirements of the Building\nCode of Australia. A contract of insurance for the residential development shall be in\nforce in accordance with Part 6 of the Home Building Act 1989.","stage":"general","stage_basis":"heading","page":14},{"label":"6","code":null,"number":"6","title":"","text":"Prior to the release of the Construction Certificate, the developer is to enter into a\nplanning agreement with Council under s.93F of the Environmental Planning and\nAssessment Act 1979 in accordance with the letter of offer made by the developer in\nconnection with the development application as set out in the letter dated 13 October\n2017 by The Bathla Group to Penrith City Council. The planning agreement requires\nthe inclusion of a detailed planting and embellishment plan of the unformed road.\nThe developer is to bear all costs associated with the processing and execution of the\nplanning agreement.","stage":"before_cc","stage_basis":"text-under-general-heading","page":14},{"label":"7","code":null,"number":"7","title":"An Asset Protection Zone for protection from bushfire shall be provided and","text":"maintained to the development in accordance with the recommendations outlined in\nthe Bushfire Protection Assessment Report prepared by ABPP Pty Ltd dated 29\nAugust 2017 and the Bushfire Safety Authority issued by the NSW Rural Fire Service\ndated 19 September 2017.\nA positive covenant is to be registered on title for the maintenance and management\nof the required Asset Protection Zone prior to the issue of an Occupation Certificate.\nThe authority to release or modify the restriction must be Penrith City Council.","stage":"general","stage_basis":"heading","page":14},{"label":"8","code":null,"number":"8","title":"The conditions imposed by the NSW Rural Fire Service in the Integrated","text":"Development consent and in the Bush Fire Safety authority for the said development\nare to be completed prior to the issue of an Occupation Certificate.","stage":"general","stage_basis":"heading","page":14},{"label":"9","code":null,"number":"9","title":"Prior to the issue of an Occupation Certificate, a design verification statement","text":"from a qualified designer shall be submitted. The design verification statement shall\nverify that the development achieves the design quality shown in the approved\nConstruction Certificate plans and specifications, having regard to the design quality\nprinciples set out in State Environmental Planning Policy No. 65 - Design Quality of\nResidential Apartment Development.","stage":"before_oc","stage_basis":"text-under-general-heading","page":14},{"label":"10","code":null,"number":"10","title":"The approved architectural floor plans shall provide compliant balconies for all","text":"apartments, including areas and dimensions that satisfy the Apartment Design Guide.\nAppeal No. 63151 of 2017\nAny required increases to areas or dimensions cannot be achieved by outwards\nextensions, and must be achieved by revised apartment floor plans\nThe design verification statement is also required to confirm the above requirements\nhave been met.","stage":"general","stage_basis":"heading","page":14},{"label":"11","code":null,"number":"11","title":"Prior to issue of a construction certificate, amended architectural drawings shall","text":"be submitted to, and approved by, Penrith City Council. The amended drawings shall\naddress the following:\n(a) The external colours and finishes schedules are to be amended to provide the\n\"G5\" notation on all applicable building elevations where the `Evantage Dark\nGrey Glass' is proposed.\n(b) Balcony louvres are to be full height and forward of the balustrade on all\napplicable elevation, section and external colour and finishes schedules in\naccordance with the 'Typical Balcony Section' drawing on Drawing No. A2022 -\nSC, \"Sections\", and Revision 8 dated 25/10/2017.\n12. Prior to the issue of a Construction Certificate, the following plan amendments\nand further specifications concerning waste management shall be submitted to, and\napproved by, Penrith City Council for Buildings A, B or C:-\ni. A tug device to be provided and permanently stored within the basement for the\nmovement of 1100L bins from the chute rooms to the waste collection room.\nii. The basement entrance ramp to provide an unobstructed height clearance of\n4.5m for all waste collection vehicle movements within the basement.\niii. The basement entrance ramp gradient to be built in accordance with the\nAustralian Standards for Heavy Rigid Waste Collection Vehicles.\niv. The turntable proposed in the basement, for use by waste collection and other\nvehicles, is to be fitted with a hydraulic override system to allow the turntable to\nbe rotated in the event of a systems malfunction. The turntable design shall\naccord with the specifications provided by the manufacturer. The manufacturer's\nspecifications for operation of the turntable are to be outlined within a Waste\nManagement Operation Plan of to be submitted with the Construction\nCertificate.\nv. The approved Waste Management Plan prepared by Elephants Foot dated 19\nSeptember 2017 must be updated to include the approved architectural plans\nwhich demonstrate compliance with Penrith Development Control Plan 2014\nAppeal No. 63151 of 2017\nand Penrith Council's Waste Management Guidelines. This plan shall include\nprovision for residents to make arrangements with the building caretaker to\ndeposit items within the bulky waste room. Residents are to be made aware that\nuse of the bulky waste room is permitted only by arrangement with the building\ncaretaker, and under no circumstances should bulky waste items be brought\ninto the basement without prior confirmation of such arrangements.\nvi. The designated waste bin lift, to be provided to operate between Basement\nLevels 1 and 2, shall accord with the specifications provided by the\nmanufacturer. The lift must accommodate a minimum of 3 x 1100 litre bins plus\nat least one person with a minimum 200mm clearance between bins and a\nminimum door opening width of 1.8m.\nvii. The bulky waste collection room on Basement Level 2 shall provide a minimum\n1.8m wide pedestrian pathway around the outside of its eastern, northern and\nwestern walls. The location of the door to the loading dock shall align with the\nend of the pathway. The bulky waste collection room shall have a minimum\ninternal clear area of 15m2. The southern and western walls of the bulky waste\ncollection room on Basement Level 2 are to provide a door, or doors, with a\nminimum opening clearance of 1.8m, open outwards and be locked through the\nuse of Councils abloy key.\nviii. A door, or doors, with a minimum opening clearance of 1.8m shall be provided\non the western wall of the Bulky Waste Collection room on Basement Level 2.\nThe door/doors are to be locked through the use of an abloy key system to\nprevent resident entry into the loading bay. The door, or doors are to open\noutwards towards the entry of the loading bay and be unobstructed by the\nbollards.\nix. A pedestrian route between the lift adjacent the southern wall of Basement 2\nand the additional door required above, shall be shown as 1.2m wide painted\nline markings on the basement floor, abutting the car parking spaces and wall of\nthe loading dock, widening to a minimum of 1.8m pathway around the walls of\nthe bulky waste collection room. Five (5) bollards shall be installed along the\nouter edge of the 1.8m wide pedestrian pathway, at the 2 corners, between the\n2 corners, and between the 2 corners and the wall of the loading dock.\nAppeal No. 63151 of 2017\nx. The 10.5m turn table to provide a minimum 1m clearance from obstructions\nduring its operations and manoeuvres involving a 10.5m heavy rigid waste\ncollection vehicle.\nxi. The northern wall of the waste collection room is to provide a door, or doors,\nwith a minimum opening clearance of 1.8m which are to open outwards towards\nthe loading bay and be locked through the use of Councils abloy key.\nxii. Specifications outlining access to the loading bay are to be provided to ensure\nCouncils collection contractors can access/open the proposed roller door\nsystem.","stage":"before_cc","stage_basis":"text-under-general-heading","page":15},{"label":"13","code":null,"number":"13","title":"","text":"Prior to issue of a construction certificate, the 'Planting Plan - Ground Floor Plan'\nand 'Planting Plan - Roof Terrace Plan' (Sheet Nos. L601 - L603), Revision 03,\ndated 15 October 2017 prepared by Place Design Group are to be amended,\nsubmitted to and approved by Penrith City Council. The amended plans shall\nincorporate the following details:\n(a) The plans shall be consistent with all details of the amended architectural\nground floor plan.\n(b) The plans shall be consistent with the masterplan in terms of the numbers and\ngeneral locations of proposed trees.\n(c) The plans shall specify finished levels for planted areas and paths, and shall be\nconsistent with levels depicted by the amended architectural ground floor plan.\n(d) The plans shall confirm, via detailed cross-sections or other means, that soil\nvolumes together with exterior walls of the approved buildings would\naccommodate proposed tree species, without inhibiting achievement of typical\nmature canopy dimensions.\n(e) The plans shall incorporate street trees (number of trees and species) which\nsatisfy the Council's Landscape Architect.\n(f) The plans shall incorporate \"Cumberland Plain Woodland\" species in the\nfollowing locations:\n(i) along setbacks to southern and western boundaries, 100% of proposed\ntrees, shrubs and understorey plantings;\n(ii) along the setback to Chapman Street: 50% of proposed trees;\n(iii) note that Kikuyu shall not be planted along any setback, and turfed areas\nin these locations shall be planted with Microlaena stipoides.\nAppeal No. 63151 of 2017\n(g) The plans shall include at least two clusters of medium height trees along the\neastern frontage of Building B.\n(h) Roof top planting on Building C shall have a height and density which prevent\noverlooking of the neighbouring townhouses to the east from the approved\ncommunal roof top.","stage":"before_cc","stage_basis":"text-under-general-heading","page":17},{"label":"14","code":null,"number":"14","title":"Prior to the issue of a Construction Certificate, details of required substation","text":"infrastructure or hydrant boosters including landscaping or screening measures is to\nbe submitted to and approved by the accredited certifier. The location of any required\nsubstation / hydrant booster is to be positioned away from the entrance of the building\nand screened in a manner that is compatible and consistent with the built form and\nstreetscape to minimise visual impacts.","stage":"before_cc","stage_basis":"text-under-general-heading","page":18},{"label":"15","code":null,"number":"15","title":"The following community safety and crime prevention through environmental design","text":"(OPTED) requirements are required to be implemented:\nLighting\n• All outdoor/public spaces throughout the development must be lit to the\nminimum Australian Standard of AS 1158. Lighting should be consistent in\norder to reduce the contrast between shadows and illuminated areas and\nshould be designed in accordance with AS 4282 - Control of the obtrusive\neffects of outdoor lighting.\nBasement Car Parking\n• A security system must be installed on any pedestrian and vehicle entry/exit\npoints to the car park, including the lift and stairwell, to minimise opportunities\nfor unauthorised access.\n• All areas of the car park must be well-lit, with consistent lighting to prevent\nshadowing or glare.\n• Car park surfaces including walls and ceilings are to be light coloured with\ndetails included with the Construction Certificate application.\nBuilding Security & Access Control\n• Intercom, code or card locks or similar must be installed for all entries to the\nbuildings including the car parks.\n• Australian Standard 220 - door and window locks must be installed in all\ndwellings.\nAppeal No. 63151 of 2017\n• CCTV is to be provided to cover communal public space areas. Cameras must\nbe of sufficient standard to be useful for police in the event of criminal\ninvestigations. Lighting should be provided to support cameras at night\n(alternatively infra-red cameras are recommended). Signage must be\ndisplayed to indicate that CCTV cameras are in use.\n• Letter boxes are to be provided in accordance with that shown on the plans.\nGraffiti/Vandalism\n• Graffiti resistant coatings must be used to external surfaces where possible,\nincluding signage, furniture, retaining walls etc.\n• Procedures must be in place to ensure the prompt removal and/or repair of\ngraffiti or vandalism to the buildings, fencing, and common areas. This\nincludes reporting incidents to police and/or relevant authorities.\nLandscaping\n• Dense, medium height vegetation with top to bottom foliage must be avoided,\nparticularly around walkways. The use of low-level planting or high canopied\nvegetation will improve surveillance, provide clear lines of sight and avoid any\npotential concealment areas. This is particularly important for common\nlandscaped areas. Vegetation must be regularly pruned to ensure that sight\nlines are maintained.\nHERITAGE / ARCHAEOLOGICAL RELICS","stage":"general","stage_basis":"heading","page":18},{"label":"16","code":null,"number":"16","title":"","text":"If any archaeological relics are uncovered during the course of the work no further\nwork shall be undertaken until further directed by Penrith City Council or the NSW\nHeritage Office.\nThe applicant is advised that depending on the possible significance of the relics, an\narchaeological assessment and an excavation permit under the Heritage Act, 1977\nmay be required before any further work can be recommenced in that area of the\nsite.\nENVIRONMENTAL MATTERS","stage":"general","stage_basis":"heading","page":19},{"label":"17","code":null,"number":"17","title":"Erosion and sediment control measures shall be installed prior to the","text":"commencement of works on site including approved clearing of site vegetation. The\nerosion and sediment control measures are to be maintained in accordance with the\napproved erosion and sediment control plan(s) for the development and the\nAppeal No. 63151 of 2017\nDepartment of Housing's \"Managing Urban Stormwater: Soils and Construction\"\n2004.","stage":"general","stage_basis":"heading","page":19},{"label":"18","code":null,"number":"18","title":"","text":"No fill material (beyond that approved as part of this consent) is to be imported to the\nsite without the prior approval of Penrith City Council in accordance with Sydney\nRegional Environmental Plan No.20 (Hawkesbury- Nepean River) (No.2-1997). No\nrecycling of material (not including earth excavated for the basement) for use as fill\nmaterial shall be carried out on the site without the prior approval of Council.","stage":"general","stage_basis":"heading","page":20},{"label":"19","code":null,"number":"19","title":"","text":"An appropriately qualified person/s shall:\n• Supervise all filling works approved as part of this consent.\n• (On completion of filling works) carry out an independent review of all\ndocumentation relating to the filling of the site, and submit a review findings\nreport to Council and any Principal Certifying Authority. All fill material\ndocumentation is to (at minimum):\n• be prepared by an appropriately qualified person with consideration of\nall relevant guidelines, standards, planning instruments and legislation\n(e.g. EPA, NEPM, ANZECC, NH&MRC),\n• clearly state the legal property description of the fill material source site\nand the total amount of fill tested,\n• provide details of the volume of fill material to be used in the filling\noperations,\n• provide a classification of the fill material to be imported to the site in\naccordance with the NSW Environment Protection Authority's \"Waste\nClassification Guidelines\" 2009, and\n• (based on the fill classification) determine whether the fill material is\nsuitable for its intended purpose and land use and whether the fill\nmaterial will or will not pose an unacceptable risk to human health or\nthe environment.\n• Certify by way of a Compliance Certificate or other written\ndocumentation that fill materials have been placed on the site in\naccordance with all conditions of this consent and that the site will not\npose an unacceptable risk to human health or the environment. A copy\nAppeal No. 63151 of 2017\nof the Compliance Certificate or other documentation shall be\nsubmitted to Council and any Principal Certifying Authority.\nThe contact details of any appropriately qualified person/s engaged for the works\nshall be provided with the Notice of Commencement.\nIf the Principal Certifying Authority or Penrith City Council is not satisfied that suitable\nfill materials have been used on the site, further site investigations or remediation\nworks may be requested. In these circumstances the works shall be carried out prior\nto any further approved works.\n{Note: An appropriately qualified person is defined as \"a person who, in the opinion of\nCouncil, has a demonstrated experience, or access to experience in hydrology,\nenvironmental chemistry, soil science, eco-toxicology, sampling and analytical\nprocedures, risk evaluation and remediation technologies. In addition, the person will\nbe required to have appropriate professional indemnity and public risk insurance.\"}","stage":"general","stage_basis":"heading","page":20},{"label":"20","code":null,"number":"20","title":"All waste materials stored on-site that are associated with the construction activities","text":"are to be contained within a designated area such as a waste bay or bin to ensure\nthat no waste materials are allowed to enter the stormwater system or neighbouring\nproperties. The designated waste storage areas shall provide at least two waste bays\n/ bins so as to allow for the separation of wastes, and are to be fully enclosed when\nthe site is unattended.","stage":"general","stage_basis":"heading","page":21},{"label":"21","code":null,"number":"21","title":"","text":"Noise levels from and within the premises shall not exceed the relevant noise criteria\ndetailed in \"16 Chapman Street, Werrington: DA Acoustic Assessment\", prepared by\nAcoustic Logic Consultancy Pty Ltd dated 11 September 2017 (Ref.\n20161597.3/1109A/R5/GW).\nThe recommendations provided in the above-mentioned acoustic report shall be\nimplemented and incorporated into the design and construction of the development,\nand shall be shown on plans accompanying the Construction Certificate\napplication.\nA certificate is to be obtained from a qualified acoustic consultant certifying that the\ndevelopment (including the installation of plant and equipment) has been constructed\nto meet the noise criteria in accordance with the approved acoustic report. This\ncertificate is to be submitted to the Principal Certifying Authority prior to the issue of\nan Occupation Certificate.\nAppeal No. 63151 of 2017\nThe provisions of the Protection of the Environment Operations Act 1997 apply to the\ndevelopment, in terms of regulating offensive noise.","stage":"general","stage_basis":"heading","page":21},{"label":"22","code":null,"number":"22","title":"","text":"Only clean and unpolluted water is to be discharged into Penrith City Council's\nstormwater drainage system. Liquid wastes suitable for discharge to the mains sewer\nare to be discharged in accordance with Sydney Water requirements.\nIf mains sewer is not available or if Sydney Water will not allow disposal to the sewer\nthen a licensed waste contractor is to remove the liquid waste from the premises to an\nappropriate waste facility.\nThe waste contractor and waste facility are to hold the relevant licenses issued by the\nNSW Environment Protection Authority.","stage":"general","stage_basis":"heading","page":22},{"label":"23","code":null,"number":"23","title":"Prior to the issue of the Construction Certificate, a Construction Noise Impact","text":"Assessment and Management Plan is to be prepared and submitted to Council for\napproval. This assessment is to consider (at minimum) the details of the construction\nprogram, construction methods, equipment and vehicles in association with the NSW\nDepartment of Environment and Climate Change's \"Interim Construction Noise\nGuideline\" 2009.\nThe recommendations of the approved Management Plan are to be implemented and\nadhered to during the construction phase of the development.","stage":"before_cc","stage_basis":"text-under-general-heading","page":22},{"label":"24","code":null,"number":"24","title":"The construction related recommendations detailed in \"16 Chapman Street,","text":"W errington: DA Acoustic Assessment\", prepared by Acoustic Logic Consultancy Pty\nLtd 11 September 2017 (ref 20161597.3/1109A/R5/GW) are to be implemented and\ncomplied with during the construction phase of the development.","stage":"general","stage_basis":"heading","page":22},{"label":"25","code":null,"number":"25","title":"","text":"All mechanical plant and equipment is to comply with the noise criteria outlined in \"16\nChapman Street, Werrington: DA Acoustic Assessment\", prepared by Acoustic Logic\nConsultancy Pty Ltd 11 September 2017 (ref 20161597.3/1109A/R5/GW).","stage":"general","stage_basis":"heading","page":22},{"label":"26","code":null,"number":"26","title":"","text":"Wastewater from the washing of garbage bins and vehicles is not to enter the\nstormwater system.","stage":"general","stage_basis":"heading","page":22},{"label":"27","code":null,"number":"27","title":"Dust suppression techniques are to be employed during construction to reduce any","text":"potential nuisances to surrounding properties.","stage":"general","stage_basis":"heading","page":22},{"label":"28","code":null,"number":"28","title":"","text":"Mud and soil from vehicular movements to and from the site must not be deposited on\nthe road.\nAppeal No. 63151 of 2017","stage":"general","stage_basis":"heading","page":22},{"label":"29","code":null,"number":"29","title":"Should any \"unexpected finds\" occur during site excavation and earthworks including,","text":"but not limited to, the identification/finding of contaminated soils, buried building\nmaterials, asbestos, odour and/or staining, works are to cease immediately and\nPenrith City Council is to be notified. Any such \"unexpected finds\" shall be addressed\nby an appropriately qualified environmental consultant.\nAll remediation works within the Penrith Local Government Area are considered to be\nCategory 1 works under State Environmental Planning Policy 55-Remediation of\nLand. Should any contamination be found during development works and should\nremediation works be required, development consent is to be sought from Penrith City\nCouncil before the remediation works commence.","stage":"general","stage_basis":"heading","page":23},{"label":"30","code":null,"number":"30","title":"","text":"A minimum 2 metre high 18mm plywood barrier is to be constructed along the\nnorthern and eastern boundaries during the construction of the development as\nrecommended in the Acoustic Report prepared by Acoustic Logic Consultancy Pty Ltd\ndated 11 September 2017 (ref 20161597.3/1109A/R5/GW).","stage":"general","stage_basis":"heading","page":23},{"label":"31","code":null,"number":"31","title":"","text":"Prior to the commencement of any works, including the removal of any trees\nassociated with approved subdivision/development activities, an inspection for\nresident birds or aboreal mammals (including inspection of all hollows) is to be\nundertaken under the supervision of a fauna ecologist. Trees found harbouring birds\nor aboreal mammals are not to be felled until the animals that are residing in them\nhave completed their breeding cycle or voluntarily vacated.\nA local vet or wildlife rescue service are to be contacted in the case of any injured\nfauna.","stage":"before_work","stage_basis":"text-under-general-heading","page":23},{"label":"32","code":null,"number":"32","title":"","text":"Prior to the issue of a Construction Certificate, a Weed Management Plan is to be\nprepared for the development and submitted to Council for approval. The Weed\nManagement Plan is to be implemented by the applicant for a period of 5 years from\nissue of the Subdivision Certificate. Once approved by Council, the Weed\nManagement Plan and its implementation forms part of this conditions of consent.","stage":"before_cc","stage_basis":"text-under-general-heading","page":23},{"label":"33","code":null,"number":"33","title":"","text":"Prior to the issue of an Occupation Certificate, the applicant is required to enter\ninto an indemnity agreement with Penrith City Council for waste collection and access\narrangements.\nBCA COMPLIANCE REQUIREMENTS","stage":"before_oc","stage_basis":"text-under-general-heading","page":23},{"label":"34","code":null,"number":"34","title":"All aspects of the building design shall comply with the applicable performance","text":"requirements of the Building Code of Australia so as to achieve and maintain\nAppeal No. 63151 of 2017\nacceptable standards of structural sufficiency, safety (including fire safety), health and\namenity for the on-going benefit of the community. Compliance with the performance\nrequirements can only be achieved by:\ncomplying with the deemed to satisfy provisions, or\nii. formulating an alternative solution which:\n• complies with the performance requirements, or\n• is shown to be at least equivalent to the deemed to satisfy provision, or\niii. a combination of (a) and (b).\nIt is the owner's responsibility to place on display, in a prominent position within the\nbuilding at all times, a copy of the latest fire safety schedule and fire safety certificate/\nstatement for the building.","stage":"general","stage_basis":"heading","page":23},{"label":"35","code":null,"number":"35","title":"","text":"The owner of a building, to which an essential fire safety measure is applicable, shall\nprovide Penrith City Council with an annual fire safety statement for the building. The\nannual fire safety statement for a building must:\ni. deal with each essential fire safety measure in the building premises, and\nii. be given:\n• within 12 months after the last such statement was given, or\n• if no such statement has previously been given, within 12 months after\na final fire safety certificate was first issued for the building.\nAs soon as practicable after the annual fire safety statement is issued, the owner of\nthe building to which the statement relates:\n• must also provide a copy of the statement (together with a copy of the current\nfire safety schedule) to the Commissioner of New South Wales Fire Brigades,\nand\n• prominently display a copy of the statement (together with a copy of the\ncurrent fire safety schedule) in the building.\nUTILITY SERVICE REQUIREMENTS","stage":"general","stage_basis":"heading","page":24},{"label":"36","code":null,"number":"36","title":"All services (water, sewer, electricity, telephone and gas) are to be installed","text":"within any proposed public roads before final inspection of the engineering works.\nAppeal No. 63151 of 2017\nPrior to the release of Subdivision Certificate, the following service authority\nclearances shall be obtained for the approved allotments:\n• A Section 73 Compliance Certificate under the Sydney Water Act 1994 shall\nbe obtained from Sydney Water. This is required prior to the issue of the\nSubdivision Certificate; and\n• A letter from Integral Energy stating that satisfactory arrangements have been\nmade for electricity supply to all proposed residential allotments in the\nsubdivision, including any necessary easements; and\n• A letter from an approved telecommunications service provider that\nsatisfactory arrangements have been made for underground telephone\nservices to all proposed residential allotments in the subdivision, including any\nnecessary easements.\nThese clearances are to be submitted to the Principal Certifying Authority.","stage":"general","stage_basis":"heading","page":24},{"label":"37","code":null,"number":"37","title":"","text":"A Section 73 Compliance Certificate under the Sydney Water Act 1994 shall be\nobtained from Sydney Water. The application must be made through an authorised\nW ater Servicing Coordinator. Please refer to \"Your Business\" section of Sydney\nW ater's website at www.sydneywater.com.au then the \"e-developer\" icon, or\ntelephone 13 20 92.\nThe Section 73 Compliance Certificate must be submitted to the Principal Certifying\nAuthority prior to the issue of an Occupation Certificate.","stage":"general","stage_basis":"heading","page":25},{"label":"38","code":null,"number":"38","title":"","text":"Prior to the issue of a Construction Certificate, a written clearance is to be\nobtained from Endeavour Energy stating that electrical services have been made\navailable to the development or that arrangements have been entered into for the\nprovision of services to the development.\nThe Substation area shall be screened properly and the screen is to be designed in a\nmanner that is compatible and consistent with the rest of the building. Details are to\nbe submitted for consideration and approval with the construction certificate\napplication.","stage":"before_cc","stage_basis":"text-under-general-heading","page":25},{"label":"39","code":null,"number":"39","title":"Prior to the issue of a Construction Certificate, the Principal Certifying Authority","text":"shall be satisfied that telecommunications infrastructure may be installed to service\nthe premises which complies with the following:\n• The requirements of the Telecommunications Act 1997:\nAppeal No. 63151 of 2017\n• For a fibre ready facility, the NBN Co's standard specifications current at the\ntime of installation; and\n• For a line that is to connect a lot to telecommunications infrastructure external\nto the premises, the line shall be located underground.\nUnless otherwise stipulated by telecommunications legislation at the time of\nconstruction, the development must be provided with all necessary pits and pipes, and\nconduits to accommodate the future connection of optic fibre technology\ntelecommunications.\nPrior to the issue of an Occupation Certificate, written certification from all relevant\nservice providers that the telecommunications infrastructure is installed in accordance\nwith the requirements above and the applicable legislation at the time of construction,\nmust be submitted to the Principal Certifying Authority.\nCONSTRUCTION","stage":"before_cc","stage_basis":"text-under-general-heading","page":25},{"label":"40","code":null,"number":"40","title":"Stamped plans, specifications, a copy of the development consent and any other","text":"Certificates/ Information to be relied upon shall be available on site at all times during\nconstruction.\nThe following details are to be displayed in a maximum of 2 signs to be erected on the\nsite:\n• the name of the person in charge of the work site and telephone number at\nwhich that person may be contacted during work hours,\n• that unauthorised entry to the work site is prohibited,\n• the designated waste storage area must be covered when the site is\nunattended, and\n• all sediment and erosion control measures shall be fully maintained until\ncompletion of the\n• construction phase.\nSignage but no more than 2 signs stating the above details is to be erected:\n• at the commencement of, and for the full length of the, construction works\nonsite, and\n• in a prominent position on the work site and in a manner that can be easily\nread by pedestrian traffic.\nAppeal No. 63151 of 2017\nAll construction signage is to be removed when the construction and associated\nlandscaping works have been completed.","stage":"general","stage_basis":"heading","page":26},{"label":"41","code":null,"number":"41","title":"","text":"Prior to the commencement of construction works:\na) Toilet facilities at or in the vicinity of the work site shall be provided at the rate of\none toilet for every 20 persons or part of 20 persons employed at the site. Each\ntoilet provided must be:\n• a standard flushing toilet connected to a public sewer, or\n• if that is not practicable, an accredited sewage management facility\napproved by the council, or\n• alternatively, any other sewage management facility approved by\ncouncil.\nb) All excavations and backfilling associated with the erection of a building must be\nexecuted safely and in accordance with the appropriate professional standards.\nAll excavations associated with the erection of a building must be properly\nguarded and protected to prevent them from being dangerous to life or property.\nc) If an excavation associated with the erection or demolition of a building extends\nbelow the level of the base of the footings of a building on an adjoining\nallotment of land, the person causing the excavation to be made:\nmust preserve and protect the building from damage, and\nif necessary, must underpin and support the building in an approved\nmanner, and\nmust, at least 7 days before excavating below the level of the base of the\nfootings of a building on an adjoining allotment of land, give notice of\nintention to do so to the owner of the adjoining allotment of land and\nfurnish particulars of the excavation to the owner of the building being\nerected or demolished.\nThe owner of the adjoining allotment of land is not liable for any part of the cost\nof work carried out for the purposes of this condition, whether carried out on the\nallotment of land being excavated or on the adjoining allotment of land,\n(includes a public road and any other public place).\nAppeal No. 63151 of 2017\nd) If the work involved in the erection of a building is likely to cause pedestrian or\nvehicular traffic in a public place to be obstructed or rendered inconvenient, or\ninvolves the enclosure of a public place, a hoarding or fence must be erected\nbetween the work site and the public place:\n• if necessary, an awning is to be erected, sufficient to prevent any\nsubstance from, or in connection with, the work falling into the public\nplace,\n• the work site must be kept lit between sunset and sunrise if it is likely to\nbe hazardous to persons in the public place, and\n• any such hoarding, fence or awning is to be removed when the work\nhas been completed.\nPrior to the issue of the Construction Certificate, a Construction Waste\nManagement Plan is to be submitted to Council for approval. This Plan is to\naddress all waste materials generated during the construction phase of the\ndevelopment, including details of the proposed waste volumes, on site storage and\nmanagement, designated waste contractors and waste facilities","stage":"before_work","stage_basis":"text-under-general-heading","page":27},{"label":"42","code":null,"number":"42","title":"The approved Construction Waste Management Plan must be implemented and","text":"adhered to on site, with supporting documentation / receipts retained in order to verify\nthe disposal of materials in accordance with the approved Plan.","stage":"general","stage_basis":"heading","page":28},{"label":"43","code":null,"number":"43","title":"","text":"Clothes drying facilities are to be positioned and screened from public view.","stage":"general","stage_basis":"heading","page":28},{"label":"44","code":null,"number":"44","title":"","text":"Prior to the issue of a Construction Certificate, it must be demonstrated that the\ndevelopment complies with AS4299 - Adaptable Housing, AS1428.1 Design for\nAccess and mobility - general requirement for access - new building work. AS1428.4\n- tactile ground surface indicators, AS2890.6 off street car parking for people with\ndisabilities.\nA compliance certificate shall be provided prior to the issue of an Occupation\nCertificate.","stage":"before_cc","stage_basis":"text-under-general-heading","page":28},{"label":"45","code":null,"number":"45","title":"","text":"Construction works that are carried out in accordance with an approved consent that\ninvolve the use of heavy vehicles, heavy machinery and other equipment likely to\ncause offence to adjoining properties shall be restricted to the following hours in\naccordance with the NSW Environment Protection Authority Noise Control Guidelines:\n• Mondays to Fridays, 7am to 6pm\nAppeal No. 63151 of 2017\n• Saturdays, 7am to 1pm (if inaudible on neighbouring residential premises),\notherwise 8am to 1pm\n• No work is permitted on Sundays and Public Holidays.\nOther construction works carried out inside a building/tenancy and do not involve the\nuse of equipment that emits noise are not restricted to the construction hours stated\nabove.\nThe provisions of the Protection of the Environment Operations Act, 1997 in\nregulating offensive noise also apply to all construction works.\nENGINEERING REQUIREMENTS","stage":"general","stage_basis":"heading","page":28},{"label":"46","code":null,"number":"46","title":"All roadworks, stormwater drainage works, associated civil works and dedications,","text":"required to effect the consented development shall be undertaken at no cost to\nPenrith City Council.","stage":"general","stage_basis":"heading","page":29},{"label":"47","code":null,"number":"47","title":"Prior to the issue of any Construction Certificate, a Section138 Roads Act","text":"application, including payment of application and inspection fees, shall be lodged and\napproved by Penrith City Council (being the Roads Authority for any works required in\na public road). These works may include but are not limited to the following:\nVehicular crossings (including kerb reinstatement of redundant vehicular\ncrossings)\nii Concrete footpaths and or cycleways\niii Road opening for utilities and stormwater (including stormwater connection to\nPenrith City Council roads and other Penrith City Council owned drainage)\niv Road occupancy or road closures\nv The placement of hoardings, structures, containers, waster skips, signs etc. in\nthe road reserve\nvi Temporary construction access\nAll works shall be carried out in accordance with the Roads Act approval, the\ndevelopment consent, including the stamped approved plans, and Penrith City\nCouncil's specifications, guidelines and best engineering practice.\nContact Penrith City Council's City Works Department on (02) 4732 7777 or visit\nPenrith City Council's website for more information.\nNote:\nAppeal No. 63151 of 2017\ni Where Penrith City Council is the Certifying Authority for the development, the\nRoads Act approval for the above works may be issued concurrently with the\nConstruction Certificate.\nii Separate approvals may also be required from the Roads and Maritime\nServices for classified roads.\niii All works associated with the Roads Act approval must be completed prior to\nthe issue of any Occupation Certificate or Subdivision Certificate as applicable.\niv On completion of any awning over the road reserve, a certificate from a\npractising structural engineer certifying the structural adequacy of the awning is\nto be submitted to Penrith City Council before Council will inspect the works and\nissue its final approval under the Roads Act.","stage":"before_cc","stage_basis":"text-under-general-heading","page":29},{"label":"48","code":null,"number":"48","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that a Section 138 Roads Act application, including payment of application\nand inspection fees, has been lodged with, and approved by Penrith City Council\n(being the Roads Authority under the Roads Act), for the following works:\nWerrinqton Road / Rance Road\n• Construction of a conventional roundabout for B-double vehicles\n• Stage 3 Road Safety Audit\n• Relocation of any services\n• Landscape works\n• Appropriate access shall be provided for all properties that gain vehicular\naccess at this intersection\n• Rance Road realignment and removal of redundant road pavement\n• Pedestrian facilities and linkages.\nSuch works must be carried out to the satisfaction of Penrith City Council prior to the\nissue of any Occupation Certificate for the development.\nChapman Street / Walker Street / Lander Street\n• Upgrade of the pavement (half road width construction) along the full frontage\nof the site and extending 20m east along Chapman Street.\n• Footpath construction from the development to existing footpath works within\nRailway Street, minimum 1.5m wide\nAppeal No. 63151 of 2017\n• Any required drainage upgrade works (subject to Section 68 Approval)\nSuch works must be carried out to the satisfaction of Penrith City Council prior to the\nissue of any Occupation Certificate for the development.\nEngineering plans are to be prepared in accordance with the development consent,\nPenrith City Council's Design Guidelines for Engineering Works for Subdivisions and\nDevelopments, Engineering Construction Specification for Civil Works, Austroads\nGuidelines, and best engineering practice.\nContact Penrith City Council's Development Engineering Department on (02) 4732\n7777 or visit Penrith City Council's website for more information.\nW here Penrith City Council is the Certifying Authority for the development the Roads\nAct approval for the above works may be issued concurrently with the Construction\nCertificate.\nAll works associated with the Roads Act approval must be completed prior to the\nissue of any Occupation Certificate or Subdivision Certificate as applicable.","stage":"before_cc","stage_basis":"text-under-general-heading","page":30},{"label":"49","code":null,"number":"49","title":"Prior to the issue of a Subdivision Certificate, the Principal Certifying Authority","text":"and/or Certifying Authority shall ensure that an application under Section 68 of the\nLocal Government Act, including payment of application and inspection fees, has\nbeen lodged with, and approved by Penrith City Council for the stormwater drainage\nconnection of the site to the Council's system.\nEngineering plans are to be prepared in accordance with the development consent,\nPenrith City Council's Design Guidelines for Engineering Works for Subdivisions and\nDevelopments, Engineering Construction Specification for Civil Works, Austroads\nGuidelines, and best engineering practice.\nThe Engineering plans shall also include the following amendments:\ni The proposed 450mm diameter RCP pipe along Lander Street and future road\nshall be located under the kerb and gutter or roadway. No pipe shall extend\nbehind the kerb and gutter within the footpath or verge;\nii The proposed kerb inlet pit within Lander Street shall be a cast in-situ pit\ndesigned by a suitably qualified Structural Engineer. The size and layout of the\nproposed kerb inlet pit chamber shall be designed taking into consideration all\npipes to be connected within this pit. Full details shall be provided for Council\nassessment.\nAppeal No. 63151 of 2017\nContact Penrith City Council's Development Engineering Department on (02) 4732\n7777 or visit Penrith City Council's website for more information.\nAll works associated with the S68 Local Government Act Approval must be completed\nprior to the issue of any Occupation Certificate.","stage":"general","stage_basis":"heading","page":31},{"label":"50","code":null,"number":"50","title":"","text":"A Construction Certificate is to be approved by the Certifying Authority for the\nprovision of engineering works (road, drainage, earthworks, subdivision works).\nPrior to the issue of any Construction Certificate, the Certifying Authority shall\nensure that engineering plans are consistent with the stamped approved concept\nplans, and that all subdivision works have been designed in accordance with the\ndevelopment consent, Penrith City Council's Design Guidelines for Engineering\nW orks for Subdivisions and Developments, Engineering Construction Specification for\nCivil Works, Austroads Guidelines and best engineering practice.\nThe subdivision works may include but are not limited to the following:\n• Public and private roads\n• Storm water management (quantity and quality)\n• Interallotment drainage\n• Private access driveways\n• Sediment and erosion control measures\n• Flood control measures\n• Overland flow paths\n• Traffic facilities\n• Earthworks\n• Bridges, culverts, retaining walls and other structures\n• Landscaping and embellishment works\nThe Construction Certificate must be supported by engineering plans, calculations,\nspecifications and any certification relied upon.\nNote:\na) Council's Development Engineering Department can provide this service.\nContact Penrith City Council's Development Engineering Department on (02)\n4732 7777 or visit Penrith City Council's website for more information.","stage":"general","stage_basis":"heading","page":32},{"label":"51","code":null,"number":"51","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that the proposed roads have been designed in accordance with Penrith City\nCouncil's Design Guidelines for Engineering Works for Subdivisions and\nAppeal No. 63151 of 2017\nDevelopments, Engineering Construction Specification for Civil Works and the\nfollowing criteria:\nRoad No. Road\nReserve\nW idth\nCarriageway\nWidth\nVerge Width Footpath\n(1.5m wide)\nMin.\nESA\nChapman\nStreet Road\nwidening\nWidth\nbased on\nDeposited\nPlan\n1226122\nAs per\nexisting\nformed road\nwidth\nAs per\nexisting\nformed verge\nwidth\n1.5 metres 5 x 105\nA copy of the pavement design prepared and certified by a suitably qualified\ngeotechnical engineer must accompany the application for Construction Certificate.","stage":"before_cc","stage_basis":"text-under-general-heading","page":32},{"label":"52","code":null,"number":"52","title":"","text":"A Stage 3 (detailed design) Road Safety Audit (RSA) shall be undertaken in\naccordance with Austroads Guide to Road Safety Part 6: Road Safety Audit on the\nproposed roadworks by an accredited auditor who is independent of the design\nconsultant. A copy of the RSA shall accompany the design plans submitted with the\nConstruction Certificate or Roads Act application.\nPrior to the issue of the Construction Certificate or Section 138 Roads Act\napproval, the Certifying Authority shall ensure that the recommendations of the RSA\nhave been considered in the final design, through review of the Road Safety Audit\nChecklist, including Findings, Recommendations and Corrective Actions.\nA copy of the Road Safety Audit shall be submitted to Penrith City Council by the\napplicant or Certifying Authority for information purposes.","stage":"general","stage_basis":"heading","page":33},{"label":"53","code":null,"number":"53","title":"The stormwater management systems shall be provided in accordance with the","text":"concept plan/s lodged for development approval, prepared by Aurecon - reference\n241636, revision 04 dated 9 October 2017.\nEngineering plans and supporting calculations for the stormwater management\nsystems are to be prepared by a suitably qualified person and shall accompany the\napplication for a Construction Certificate.\nPrior to the issue of any Construction Certificate, the Certifying Authority shall\nensure that the stormwater management system has been designed in accordance\nwith Penrith City Council's Stormwater Drainage for Building Developments and\nW ater Sensitive Urban Design (WSUD) policies.","stage":"general","stage_basis":"heading","page":33},{"label":"54","code":null,"number":"54","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that the stormwater drainage system for the basement car park has been\nAppeal No. 63151 of 2017\ndesigned in accordance with the requirements for pumped systems in AS3500.3 (or\nas amended) (Plumbing and Drainage - Stormwater Drainage).","stage":"before_cc","stage_basis":"text-under-general-heading","page":33},{"label":"55","code":null,"number":"55","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that the structure/s below RL 25.6m AHD (standard flood level + 0.5m\nfreeboard) have been detailed with flood compatible building components in\naccordance with the publication 'Reducing the Vulnerability of Buildings to Flood\nDamage' produced by the Hawkesbury-Nepean Floodplain Management Steering\nCommittee.","stage":"before_cc","stage_basis":"text-under-general-heading","page":34},{"label":"56","code":null,"number":"56","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that all electrical services associated with the proposed building works are\nadequately flood proofed in accordance with Penrith City Council's Development\nControl Plan relating to flood liable land. Flood sensitive equipment (including electric\nmotors and switches) shall also be located above RL 25.6 m AHD (standard flood\nlevel + 0.5m freeboard).","stage":"before_cc","stage_basis":"text-under-general-heading","page":34},{"label":"57","code":null,"number":"57","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that:\nHabitable floor levels are a minimum of RL 25.6m AHD (standard flood level +\n0.5m freeboard).\nii The proposed development will not concentrate, dam or divert overland flows\nonto adjoining properties.\niii The crest in the access ramp to the basement car park is a minimum of RL\n25.4m AHD or 0.3m above the top of kerb (whichever is greater).\niv All proposed penetrations and access points into the basement carpark area\nminimum of 0.3m above the top water level adopted for the flooding.\nDetails prepared by a qualified person, demonstrating compliance with these\nrequirements, shall form part of any Construction Certificate issued.","stage":"before_cc","stage_basis":"text-under-general-heading","page":34},{"label":"58","code":null,"number":"58","title":"Prior to the issue of any Construction Certificate, the Certifying Authority shall","text":"ensure that vehicular access, circulation, manoeuvring, pedestrian and parking areas\nassociated with the subject development are in accordance with AS 2890.1,\nAS2890.2, AS2890.6 and Penrith City Council's Development Control Plan.","stage":"before_cc","stage_basis":"text-under-general-heading","page":34},{"label":"59","code":null,"number":"59","title":"Prior to the issue of a Construction Certificate, the Certifying Authority shall","text":"ensure that a Construction Traffic Management Plan (CTMP) has been submitted to\nAppeal No. 63151 of 2017\nand approved by Penrith City Council. Approval of the CTMP may require\nendorsement from the Local Traffic Committee. The CTMP shall include, but not\nlimited to the following: vehicle routes, number of construction vehicles, hours of\noperation, access arrangements, pedestrian management, turning templates for\nnarrow streets and intersections and parking management for workers. The CTMP\nshall be certified by an appropriately accredited person and/or Roads and Traffic\nAuthority Traffic Controller.The CTMP shall be certified by an appropriately accredited\nperson and/or Roads and Traffic Authority Traffic Controller. The CTMP shall ensure\nthat adequate parking is provided for the development and not severely impacted by\nthe construction of this development.\nThe TMP shall be supported by a traffic control plan, designed in accordance with the\nrequirements of the Roads and Traffic Authority's Manual, Traffic Control at Work\nSites Version 2, and the current Australian Standards, Manual of Uniform Traffic\nControl Devices Part 3, 'Traffic Control Devices for Works on Roads'.\nThe traffic control plan must be prepared by a suitably qualified and RTA accredited\nW ork Site Traffic Controller.","stage":"before_cc","stage_basis":"text-under-general-heading","page":34},{"label":"60","code":null,"number":"60","title":"","text":"Prior to the issue of a Roads Act Approval, a Performance Bond is to be lodged\nwith Penrith City Council for works in Werrington Road, Rance Road, Landers Street\nand Chapman Street.\nThe value of the bond shall be determined in accordance with Penrith City Council's\nadopted Fees and Charges.\nNote:\nContact Penrith City Council's Development Engineering Department on (02) 4732\n7777 for further information relating to bond requirements.","stage":"general","stage_basis":"heading","page":35},{"label":"61","code":null,"number":"61","title":"","text":"Prior to the issue of a Construction Certificate the Certifying Authority shall ensure\nthat a Geotechnical investigation, report and strategy has been conducted to ensure\nstability of the Council infrastructure and surrounding developments. The geotechnical\ninvestigation, report and strategy shall comply with the recommendations contained in\nthe technical direction GTD 2012/001 prepared by the Road and Maritime Services as\namended. The development shall undertake a dilapidation report for all surrounding\nbuildings and Council owned infrastructure that confirms that no damage occurs due\nto the excavations associated with the development. If Council is not the Certifying\nAuthority the dilapidation report shall be submitted to Council prior to Construction\nAppeal No. 63151 of 2017\nCertificate and then updated and submitted prior to any Occupation Certificate\nconfirming no damage has occurred.","stage":"before_cc","stage_basis":"text-under-general-heading","page":35},{"label":"62","code":null,"number":"62","title":"Prior to the issue of any Construction Certificate issued for internal works","text":"associated with the development, the site must be served by a legal point of\ndischarge including any required infrastructure drainage works. The drainage works\nmay include inter-allotment drainage construction, upgrades and / or road drainage\nextensions located on lands owned by others.","stage":"before_cc","stage_basis":"text-under-general-heading","page":36},{"label":"63","code":null,"number":"63","title":"Prior to commencement of any works associated with the development, sediment","text":"and erosion control measures shall be installed in accordance with the approved\nConstruction Certificate and to ensure compliance with the Protection of the\nEnvironment Operations Act 1997 and Managing Urban Stormwater series from the\nOffice of Environment and Heritage.\nThe erosion and sediment control measures shall remain in place and be maintained\nuntil all disturbed areas have been rehabilitated and stabilised.","stage":"before_work","stage_basis":"text-under-general-heading","page":36},{"label":"64","code":null,"number":"64","title":"Prior to commencement of any works associated with the development, a Traffic","text":"Control Plan, including details for pedestrian management, shall be prepared in\naccordance with AS1742.3 \"Traffic Control Devices for Works on Roads\" and the\nRoads and Maritime Services' publication \"Traffic Control at Worksites\" and certified\nby an appropriately accredited Roads and Maritime Services Traffic Controller.\nTraffic control measures shall be implemented during the construction phase of the\ndevelopment in accordance with the certified plan. A copy of the plan shall be\navailable on site at all times.\nA copy of the Traffic Control Plan shall accompany the Notice of Commencement to\nPenrith City Council.","stage":"before_work","stage_basis":"text-under-general-heading","page":36},{"label":"65","code":null,"number":"65","title":"Work on the approved development (including any subdivision works) shall not","text":"commence until:\n• a Construction Certificate and any S68 approval has been issued,\n• a Principal Certifying Authority has been appointed for the project, and\n• any other matters prescribed in the development consent for the subdivision\nand the Environmental Planning and Assessment Act and Regulation have\nbeen complied with.\nAppeal No. 63151 of 2017\nA Notice of Commencement of works is to be submitted to Penrith City Council five\n(5) days prior to commencement of engineering works or clearing associated with the\nsubdivision.","stage":"general","stage_basis":"heading","page":36},{"label":"66","code":null,"number":"66","title":"","text":"A certificate by a registered surveyor verifying that all habitable floor levels are at or\nabove RL 25.6m AHD (standard flood level + 0.5m freeboard) shall be submitted\nupon completion of the building to that level. No further construction of the building is\nto be carried out until approval to proceed is issued by the Principal Certifying\nAuthority.","stage":"general","stage_basis":"heading","page":37},{"label":"67","code":null,"number":"67","title":"","text":"Street lighting is to be provided for all new and existing streets within the proposed\nsubdivision to Penrith City Council's standards.","stage":"general","stage_basis":"heading","page":37},{"label":"68","code":null,"number":"68","title":"","text":"All earthworks shall be undertaken in accordance with AS 3798 and Penrith City\nCouncil's Design Guidelines for Engineering Works for Subdivisions and\nDevelopments and Engineering Construction Specification for Civil Works.\nThe level of testing shall be determined by the Geotechnical Testing Authority/\nSuperintendent in consultation with the Principal Certifying Authority.","stage":"general","stage_basis":"heading","page":37},{"label":"69","code":null,"number":"69","title":"","text":"Upon completion of all works in the road reserve, all verge areas fronting and within\nthe development are to be turfed. The turf shall extend from the back of kerb to the\nproperty boundary, with the exception of concrete footpaths, service lids or other\ninfrastructure which is not to be turfed over. Turf laid up to concrete footpaths, service\nlids or other infrastructure shall finish flush with the edge.","stage":"general","stage_basis":"heading","page":37},{"label":"70","code":null,"number":"70","title":"All existing (aerial) and proposed services for the development, including those","text":"across the frontage of the development are to be located or relocated underground in\naccordance with the relevant authorities regulations and standards.","stage":"general","stage_basis":"heading","page":37},{"label":"71","code":null,"number":"71","title":"Prior to the issue of any Occupation Certificate and/or Subdivision Certificate,","text":"the Principal Certifying Authority shall ensure that all works associated with a S138\nRoads Act approval and any S68 Local Government Act approval have been\ninspected and signed off by Penrith City Council.","stage":"before_oc","stage_basis":"text-under-general-heading","page":37},{"label":"72","code":null,"number":"72","title":"Prior to the issue of a Subdivision Certificate, the Principal Certifying Authority","text":"shall ensure that all subdivision works required by this consent have been\nsatisfactorily completed or that suitable arrangements have been made with Penrith\nCity Council for any outstanding works.\nAppeal No. 63151 of 2017","stage":"general","stage_basis":"heading","page":37},{"label":"73","code":null,"number":"73","title":"Prior to the issue of any Occupation Certificate and/or Subdivision Certificate,","text":"works-as-executed drawings, final operation and maintenance management plans\nand any other compliance documentation shall be submitted to the Principal Certifying\nAuthority in accordance with Penrith City Council's Engineering Construction\nSpecification for Civil Works, WSUD Technical Guidelines and Stormwater Drainage\nfor Building Developments.\nAn original set of Works As Executed drawings and copies of the final operation and\nmaintenance management plans and compliance documentation shall also be\nsubmitted to Penrith City Council with notification of the issue of the Occupation\nand/or Subdivision Certificate where Penrith City Council is not the Principal Certifying\nAuthority.","stage":"before_oc","stage_basis":"text-under-general-heading","page":38},{"label":"74","code":null,"number":"74","title":"Prior to the issue of any Occupation Certificate, the Principal Certifying Authority","text":"shall ensure that the:\nStormwater management systems (including on-site detention and water\nsensitive urban design)\nii Flood control works\n• Have been satisfactorily completed in accordance with the approved\nConstruction Certificate and the requirements of this consent.\n• Have met the design intent with regard to any construction variations to\nthe approved design.\n• Any remedial works required to been undertaken have been\nsatisfactorily completed.\nDetails of the approved and constructed system/s shall be provided as part of the\nW orks As Executed drawings.","stage":"before_oc","stage_basis":"text-under-general-heading","page":38},{"label":"75","code":null,"number":"75","title":"","text":"Prior to the issue of any Occupation Certificate, a restriction as to user and\npositive covenant relating to the maintenance of:\nStormwater management systems (including on-site detention and water\nsensitive urban design); and\nii Flood control works\nAppeal No. 63151 of 2017\nshall be registered on the title of the property. The restriction as to user and positive\ncovenant shall be in Penrith City Council's standard wording as detailed in Penrith\nCity Council's Stormwater and Drainage for Building Developments policy.","stage":"before_oc","stage_basis":"text-under-general-heading","page":38},{"label":"76","code":null,"number":"76","title":"","text":"Prior to the issue of any Subdivision Certificate, an easement for drainage and\noverland flow shall be provided over proposed Lot 32 in favour of proposed Lot 31,\nand evidence of registration of the easement with Land and Property Information (LPI)\nshall be submitted to the Principal Certifying Authority and Penrith City Council, if\nPenrith City Council is not the Principal Certifying Authority. Easement widths shall be\nin accordance with Penrith City Council's Stormwater Drainage policy. The easement\nshall cover any drainage infrastructure required to drain proposed Lot 31.","stage":"general","stage_basis":"heading","page":39},{"label":"77","code":null,"number":"77","title":"Prior to the issue of any Occupation Certificate and/or Subdivision Certificate, a","text":"Maintenance Bond is to be lodged with Penrith City Council all works associated with\na S138 approval and/or S68 approval.\nThe value of the bond shall be determined in accordance with Penrith City Council's\nadopted Fees and Charges.\nNote:\ni Contact Penrith City Council's Engineering Services Department on (02) 4732\n7777 for further information relating to bond requirements.","stage":"before_oc","stage_basis":"text-under-general-heading","page":39},{"label":"78","code":null,"number":"78","title":"","text":"Prior to the issue of any Occupation Certificate and prior to the issue of any\nSubdivision Certificate the following compliance documentation shall be submitted\nto the Principal Certifying Authority. A copy of the following documentation shall be\nprovided to Penrith City Council where Penrith City Council is not the Principal\nCertifying Authority:\nW orks As Executed (WAE) drawings of all civil works. The WAE drawings shall\nbe marked in red on copies of the stamped Construction Certificate drawings\nsigned, certified and dated by a registered surveyor or the design engineer. The\nW AE drawings shall be prepared in accordance with Penrith City Council's\nEngineering Construction Specification for Civil Works.\nii CCTV footage in DVD format to Penrith City Council's requirements and a\nreport in \"SEWRAT\" format for all drainage as identified as Council's future\nassets. Any damage that is identified is to be rectified in consultation with\nPenrith City Council.\nAppeal No. 63151 of 2017\niii A copy of all documentation, reports and manuals required by Section 2.6 of\nPenrith City Council's WSUD Technical Guidelines for handover of stormwater\nmanagement facilities to Penrith City Council.\niv Surveyor's Certificate certifying that all pipes and services are located wholly\nwithin the property or within appropriate easements and that no services\nencroach boundaries.\nv Documentation for all road pavement materials used demonstrating compliance\nwith Penrith City Council's Engineering Construction Specification for Civil\nW orks.\nvi A Geotechnical Report certifying that all earthworks and road formation have\nbeen completed in accordance with AS3798 and Penrith City Council's Design\nGuidelines and Construction specifications. The report shall include:\n• Compaction reports for road pavement construction; and\n• Statement of Compliance with that Standard those Guidelines and\nspecifications and any applicable conditions of development consent.","stage":"before_oc","stage_basis":"text-under-general-heading","page":39},{"label":"79","code":null,"number":"79","title":"The stormwater management systems shall continue to be operated and maintained","text":"in perpetuity for the life of the development in accordance with the final operation and\nmaintenance management plan.\nRegular inspection records are required to be maintained and made available to\nPenrith City Council on request. All necessary improvements are required to be\nmade immediately upon awareness of any deficiencies in the stormwater\nmanagement systems.","stage":"general","stage_basis":"heading","page":40},{"label":"80","code":null,"number":"80","title":"","text":"The following car parking and basement design requirements must be met prior to\nthe issue of an Occupation Certificate:-\n• All car parking and manoeuvring must be in accordance with AS2890.1-2004;\nAS2890.6-2009 and Council's requirements.\n• The required sight lines around the driveway entrances are not to be\ncompromised by landscaping, fencing or signage.\n• All vehicles are to be able to enter and exit the site in a forward direction.\n• Secure bicycle parking is to be provided at convenient location(s) in\naccordance with AS2890.3:2015 Bicycle Parking Facilities.\nAppeal No. 63151 of 2017\n• Appropriate signage and arrows are to be displayed to reinforce designated\nvehicle circulation and parking arrangements.\n• Subleasing of car parking spaces is prohibited.\n• Signage indicating the location of visitor and service vehicle parking is\nrequired at the driveway entrance.\nLANDSCAPING AND VEGETATION MANAGEMENT","stage":"general","stage_basis":"heading","page":40},{"label":"81","code":null,"number":"81","title":"","text":"All landscape works are to be constructed in accordance with the landscape plan(s)\nrequired to be approved by this consent and Landscape Design section of Penrith\nCouncil's Development Control Plan 2014.\nLandscaping shall be maintained:\n• in accordance with the approved plan, and\n• in a healthy state, and in perpetuity by the existing or future owners and\noccupiers of the property.\nAll landscape works are to meet industry best practice and the following relevant\nAustralian Standards:\n• AS 4419 Soils for Landscaping and Garden Use,\n• AS 4454 Composts, Soil Conditioners and Mulches, and\n• AS 4373 Pruning of Amenity Trees.\nIf any of the vegetation comprising that landscaping dies or is removed, it is to be\nreplaced with vegetation of the same species and, to the greatest extent practicable,\nthe same maturity as the vegetation which died or was removed.\nThe approved landscaping for the site must be carried out by a suitably qualified and\nexperienced landscape professional.","stage":"general","stage_basis":"heading","page":41},{"label":"82","code":null,"number":"82","title":"Upon completion of the landscape works associated with the development and prior","text":"to the issue of an Occupation Certificate for the development, an Implementation\nReport must be submitted to the Principal Certifying Authority attesting to the\nsatisfactory completion of the landscaping works for the development. The report is to\nbe prepared by a suitably qualified Landscape Architect.\nAn Occupation Certificate is not to be issued until such time as a satisfactory\nImplementation Report has been received. If Penrith City Council is not the Principal\nAppeal No. 63151 of 2017\nCertifying Authority, a copy of the satisfactory Implementation Report is to be\nsubmitted to Council together with the Occupation Certificate for the development.","stage":"general","stage_basis":"heading","page":41},{"label":"83","code":null,"number":"83","title":"","text":"No fill, machinery, fire access link or materials are to be placed or stored within the\ndrip line of any tree that is to be retained. Tree protection measures are to be\nimplemented as outlined in Australian Standard AS 4970-2009 'Protection of trees on\ndevelopment sites'.","stage":"general","stage_basis":"heading","page":42},{"label":"84","code":null,"number":"84","title":"","text":"No trees are to be removed from within the land the subject of the approved\nsubdivision or from the site of the approved development without the prior consent of\nPenrith City Council (unless specifically approved for removal as part of this consent).\nAny trees to be removed as part of the engineering works are to be shown on\nengineering plans submitted with the construction certificate application.\nAll trees approved by Council for removal shall be removed in a manner so as to\nprevent damage to those trees that are to be retained.","stage":"general","stage_basis":"heading","page":42},{"label":"85","code":null,"number":"85","title":"","text":"All trees required to be retained as part of this consent (including those within 8m of\nproposed lot 31) shall be duly protected during the construction of the development.\nTree protection measures shall:\n• be installed before any works can commence on site including the clearing of\nsite vegetation, and\n• be certified by an arborist before any works can commence on site. The\ncertification is to be a Compliance Certificate or other written document\ncertifying suitable tree protection measures have been installed. The\nCompliance Certificate or other suitable documentation shall be submitted to\nthe Principal Certifying Authority a minimum 2 days prior to the\ncommencement of site works. A copy of the Compliance Certificate or written\ndocumentation is to be submitted to Council with the \"Notice of\nCommencement\".","stage":"general","stage_basis":"heading","page":42},{"label":"86","code":null,"number":"86","title":"","text":"Prior to the issue of an Occupation Certificate, street trees are to be planted as\nper the approved Landscape Plan and in accordance with Penrith City Council's\nEngineering Works Development Control Plan, the Guidelines for Engineering Works\nfor Subdivisions and Developments Part 1-Design and Part 2-Construction and\nPenrith City Council's Landscape Development Control Plan.\nBefore the street trees are planted, approval of the plant species and location of the\nstreet trees are to be approved by Penrith City Council (as the relevant Roads\nAppeal No. 63151 of 2017\nAuthority). In this regard, please contact Council's Development Services Unit on\n4732 7777.\nSUBDIVISION REQUIREMENTS","stage":"before_oc","stage_basis":"text-under-general-heading","page":42},{"label":"87","code":null,"number":"87","title":"","text":"Work on the subdivision is not to commence until:\n• a Construction Certificate has been issued,\n• a Principal Certifying Authority has been appointed for the project, and\n• any other matters required to be undertaken by these conditions of\ndevelopment consent, or prescribed by the Environmental Planning and\nAssessment Act and Environmental Planning and Assessment\nRegulation have been complied with.\nPenrith City Council is to be notified 48 hours prior to commencement of engineering\nworks or clearing associated with the subdivision.","stage":"general","stage_basis":"heading","page":43},{"label":"88","code":null,"number":"88","title":"","text":"Any application for release of a Subdivision Certificate must be accompanied by the\noriginal Linen Plan and six 6) copies.\nAll drainage easements, rights of way, restrictions and covenants are to be included\non the linen plan.\nAll dedications of roads and drainage are to be undertaken at no cost to Penrith City\nCouncil.\nThe following information is to be shown on one (1) copy of the plan.\n• The location of all buildings and any other permanent improvements shall\ncomply with any statutory boundary clearances or setbacks as defined by the\nBuilding Code of Australia and Council's resolutions.\n• All existing services are wholly contained within the lot served or contained\nwithin the site of an appropriate easement.\nDEVELOPMENT CONTRIBUTIONS","stage":"general","stage_basis":"heading","page":43},{"label":"89","code":null,"number":"89","title":"This condition is imposed in accordance with Penrith City Council's Section 94","text":"Contributions Plan(s) for:\n• CW - Cultural Facilities;\n• CW - District Open Space; and\n• Werrington Enterprise Living and Learning (WELL) Precinct\nThese plans can be inspected at Council's Civic Centre, 601 High Street, Penrith.\nAppeal No. 63151 of 2017\nA development contribution of $25,859.00 per dwelling is payable in accordance with\nthe above Contribution Plans.\nThis amount is to be paid to Council prior to a Construction Certificate being issued\nfor this development (the rates are subject to quarterly reviews). If not paid within the\ncurrent quarterly period, this contribution will be reviewed at the time of payment in\naccordance with the adopted Section 94 Plan. The projected rates of this contribution\namount are listed in Council's Fees and Charges Schedule.\nCouncil should be contacted prior to payment to ascertain the rate for the current\nquarterly period.\nNote: No section 94 Contributions have been generated for Proposed Lot 32 and 33 as\nthese lots will be levied for Section 94 contributions when a future development\napplication is lodged in regard to their development.\nCERTIFICATION","stage":"general","stage_basis":"heading","page":43},{"label":"90","code":null,"number":"90","title":"","text":"All roadworks, dedications and drainage works are to be carried out at the applicant's\ncost.","stage":"general","stage_basis":"heading","page":44},{"label":"91","code":null,"number":"91","title":"","text":"Prior to the commencement of any earthworks or construction works on site, the\nproponent is to:\nemploy a Principal Certifying Authority to oversee that the said works carried out\non the site are in accordance with the development consent and related\nConstruction Certificate issued for the approved development, and with the\nrelevant provisions of the Environmental Planning and Assessment Act and\naccompanying Regulation, and\nii submit a Notice of Commencement to Penrith City Council.\nThe Principal Certifying Authority shall submit to Council an \"Appointment of Principal\nCertifying Authority\" in accordance with Section 81A of the Environmental Planning\nand Assessment Act 1979.\nInformation to accompany the Notice of Commencement\nTwo (2) days before any earthworks or construction/demolition works are to\ncommence on site (including the clearing site vegetation), the proponent shall submit\na \"Notice of Commencement\" to Council in accordance with Section 81A of the\nEnvironmental Planning and Assessment Act 1979.\nAppeal No. 63151 of 2017","stage":"before_work","stage_basis":"text-under-general-heading","page":44},{"label":"92","code":null,"number":"92","title":"","text":"A Subdivision Certificate is to be obtained prior to the release of the linen plan of\nsubdivision. The Subdivision Certificate will not be issued if any of the conditions in\nthis consent relating to subdivision works are outstanding.\nG Brown\nCommissioner of the Court","stage":"general","stage_basis":"heading","page":45}]});
